#!/usr/bin/env python3
"""Public 512-byte programs, generated by the locked original recompiler."""
import argparse
import hashlib
import json
import pathlib
import struct
import subprocess
from prepare_overlay_fixtures import fnv

ROOT = pathlib.Path(__file__).resolve().parents[1]


def prepare(output):
    lock = json.loads((ROOT / 'dependencies.lock.json').read_text())
    revision = subprocess.check_output(['git', '-C', str(ROOT / 'upstream/Yakumo'), 'rev-parse', 'HEAD'], text=True).strip()
    assert revision == lock['repositories']['yakumo']['commit']
    compiler = ROOT / 'out/framework/psp_recomp'
    output.mkdir(parents=True, exist_ok=True)
    modules = []
    catalog = '// SPDX-License-Identifier: GPL-3.0-or-later\n'
    declarations = ''
    rows = []
    for index in range(32):
        base = 0x08910000 + (index % 2) * 0x1000
        prefix = f'integration_{index:02d}'
        immediate, mask, tag = index + 3, index * 17 + 5, index + 401
        code_size = 256 if (index // 2) % 2 == 0 else 128
        # Save return; integer + bit arithmetic; a bounded three-iteration loop
        # with a useful branch delay slot; host HLE call; guest data stores;
        # useful return delay slot. Constants and oracle are independently tested.
        words = [0x03E07821, 0x24840000 | immediate, 0x38840000 | mask,
                 0x24080003, 0x24840002, 0x2508FFFF, 0x1500FFFD, 0x24840001,
                 0x0C000000 | (0x08806000 >> 2), 0x24840004,
                 0xACA20000, 0x24030000 | tag, 0xACA30004, 0x01E00008, 0xACA40008]
        words += [0] * (code_size // 4 - len(words))
        # Long-only function lies beyond the short code range.
        if code_size == 256:
            words[48:51] = [0x24020063, 0x03E00008, 0]
        header = bytearray(64)
        header[:4] = b'MWo3'
        struct.pack_into('<IIIIIII', header, 4, tag, base, code_size, 512 - 64 - code_size, 0, base + 512, base + 512)
        header[32:32 + len(prefix)] = prefix.encode()
        image = bytes(header) + struct.pack('<' + 'I' * len(words), *words) + bytes(512 - 64 - code_size)
        elf = bytearray(84)
        elf[:7] = b'\x7fELF\x01\x01\x01'
        struct.pack_into('<HHIIIIIHHHHHH', elf, 16, 2, 8, 1, base + 64, 52, 0, 0, 52, 32, 1, 40, 0, 0)
        struct.pack_into('<IIIIIIII', elf, 52, 1, 148, base + 64, base + 64, code_size, code_size, 5, 4)
        content = bytes(elf) + image
        directory = output / prefix
        directory.mkdir(exist_ok=True)
        fixture = directory / 'synthetic.elf'
        if not fixture.exists() or fixture.read_bytes() != content:
            fixture.write_bytes(content)
        generated = directory / 'generated'
        command = [str(compiler), str(fixture), '--auto', str(generated), hex(base), '4096', '--prefix', prefix]
        signature = hashlib.sha256(content + compiler.read_bytes()).hexdigest()
        stamp = directory / 'generation.sha256'
        if not stamp.exists() or stamp.read_text() != signature:
            result = subprocess.run(command, text=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, check=True)
            (directory / 'generation.log').write_text(result.stdout)
            stamp.write_text(signature)
        identity = fnv(image[:64 + code_size])
        wrapper = f'''// SPDX-License-Identifier: GPL-3.0-or-later
#define MHP3RD_OVERLAY_MODULE 1
#include "overlay_module.hpp"
#include "psprecomp/runtime.hpp"
namespace psprecomp {{ void register_{prefix}_functions(Runtime&); }}
namespace {{ constexpr mhp3rd::OverlayModuleInfo info{{mhp3rd::kOverlayAbiVersion, {base}u, 512u, {code_size}u, {identity}ull, "{prefix}"}}; }}
extern "C" const mhp3rd::OverlayModuleInfo* {prefix}_info() {{ return &info; }}
extern "C" void {prefix}_install(psprecomp::Runtime& runtime) {{ psprecomp::register_{prefix}_functions(runtime); }}
'''
        path = directory / 'module.cpp'
        if not path.exists() or path.read_text() != wrapper:
            path.write_text(wrapper)
        declarations += f'extern "C" const mhp3rd::OverlayModuleInfo* {prefix}_info();\nextern "C" void {prefix}_install(psprecomp::Runtime&);\n'
        catalog += f'constexpr unsigned char {prefix}_image[] = {{' + ','.join(map(str, image)) + '};\n'
        rows.append(f'#if YAKUMO_INTEGRATION_MODULE_COUNT > {index}\n{{{prefix}_info, {prefix}_install, {prefix}_image, {immediate}, {mask}, {tag}}},\n#endif')
        modules.append(dict(name=prefix, base=base, code_size=code_size, image_bytes=512, fnv1a64=identity, command=command))
    catalog = declarations + catalog + 'constexpr IntegrationModule integration_modules[] = {\n' + '\n'.join(rows) + '\n};\n'
    path = output / 'integration_catalog.inc'
    if not path.exists() or path.read_text() != catalog:
        path.write_text(catalog)
    files = {p.relative_to(output).as_posix(): hashlib.sha256(p.read_bytes()).hexdigest()
             for p in sorted(output.rglob('*')) if p.is_file() and p.name != 'fixture-manifest.json'}
    (output / 'fixture-manifest.json').write_text(json.dumps(dict(yakumo=revision, synthetic_only=True,
        generator_sha256=hashlib.sha256(compiler.read_bytes()).hexdigest(), modules=modules, files=files), indent=2) + '\n')
    print('Verified 32 public integration modules; no commercial inputs')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=pathlib.Path, required=True)
    prepare(parser.parse_args().output)
